# NI-05: validação proporcional de preparação. Não executa validadores/evidências KF anteriores.
$ErrorActionPreference='Stop'
if($PSScriptRoot){$repoRoot=Split-Path -Parent $PSScriptRoot}else{$repoRoot=(Get-Location).Path}
$checkpoint='5c425c13ede4f72e4ba01f24def21dfb40a6740d'
$output=Join-Path $repoRoot 'validation/evidence/ni-validation.json'
$baseline=Get-Content -Raw -Encoding utf8 -LiteralPath (Join-Path $repoRoot 'validation/evidence/ni-baseline.json')|ConvertFrom-Json
$issues=New-Object System.Collections.Generic.List[string]
$modifiedAllowed=@('README.md','AGENTS.md','governance/AUTHORITY-MODEL.md','governance/PROJECT-INSTRUCTIONS.md','governance/RAG-PROTOCOL.md','governance/SOURCE-RECONCILIATION.md','decisions/DECISION-REGISTER.md','product/M01-PRODUCT-BASELINE.md','product/M01-FUNCTIONAL-REQUIREMENTS.md','validation/M01-ACCEPTANCE-CRITERIA.md','engineering/REQUIREMENT-REGISTER.md','architecture/ARCHITECTURE-BASELINE.md','planning/M01-ROADMAP.md','planning/WORK-PACKAGE-REGISTER.md','status/CURRENT-STATUS.md','status/RISK-REGISTER.md','validation/KNOWLEDGE-READINESS.md','context/PROJECT-CONTEXT.md')
$newAllowed=@('governance/sources/normative-integration-mandate-01.md','governance/SOURCE-MANIFEST.md','engineering/REQ-NORMATIVE-INTEGRATION-01.md','engineering/IMP-NORMATIVE-INTEGRATION-01.md','validation/M01-NORMATIVE-TRACEABILITY.md','status/NORMATIVE-CONFLICT-REGISTER.md','validation/VAL-NORMATIVE-INTEGRATION-01.md','status/NI-DELIVERY-HANDOFF.md','validation/validate-normative-integration.ps1','validation/evidence/ni-baseline.json','validation/evidence/ni-validation.json')
$historical=@()
foreach($f in $baseline.files){$p=Join-Path $repoRoot $f.path;if(-not (Test-Path -LiteralPath $p)){$issues.Add('Arquivo inicial excluído: '+$f.path);continue};if($modifiedAllowed -notcontains $f.path){$after=(Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash.ToLower();$ok=$after -eq $f.sha256;$historical+=@{path=$f.path;before_sha256=$f.sha256;after_sha256=$after;unchanged=$ok};if(-not $ok){$issues.Add('Histórico alterado fora do escopo: '+$f.path)}}}
$docs=@(Get-ChildItem -Recurse -File -LiteralPath $repoRoot -Filter '*.md' | Where-Object {$_.FullName -notmatch '[\\/]\.git[\\/]'})
$ids=@{};$links=0;$metadata=0
foreach($f in $docs){$rel=$f.FullName.Substring($repoRoot.Length+1).Replace('\','/');$t=[System.IO.File]::ReadAllText($f.FullName);$h=[regex]::Match($t,'(?s)\A---\r?\n(.*?)\r?\n---\r?\n');if(-not $h.Success){$issues.Add('Frontmatter ausente: '+$rel);continue};$m=$h.Groups[1].Value;$metadata++
 foreach($k in @('id','title','version','status','authority','maintainer','module','classification','references','supersedes','last_updated')){if($m -notmatch ('(?m)^'+$k+':\s*')){$issues.Add('Metadata ausente: '+$rel+' / '+$k)}}
 $id=[regex]::Match($m,'(?m)^id:\s*(\S+)').Groups[1].Value;if($ids.ContainsKey($id)){$issues.Add('ID duplicado: '+$id)}else{$ids[$id]=$rel}
 if($m -notmatch '(?m)^classification: PUBLIC\s*$'){$issues.Add('Classificação não pública: '+$rel)}
 if($t.Contains([char]0xFFFD)){$issues.Add('Caractere de substituição: '+$rel)}
 if(([regex]::Matches($t,'(?m)^```').Count % 2) -ne 0){$issues.Add('Code fence não fechado: '+$rel)}
 $targets=@([regex]::Matches($t.Substring($h.Length),'\]\(([^)]+)\)') | ForEach-Object {$_.Groups[1].Value});$targets+=@([regex]::Matches($m,'(?m)^  - "([^"\r\n]+)"\s*$')|ForEach-Object {$_.Groups[1].Value})
 foreach($target in $targets){if($target -match '^(https?:|mailto:|#)'){continue};$links++;$p=[System.IO.Path]::GetFullPath((Join-Path $f.DirectoryName (($target.Trim('<','>') -split '#',2)[0])));if($p -eq $output){continue};if(-not (Test-Path -LiteralPath $p)){$issues.Add('Referência inexistente: '+$rel+' -> '+$target)}}
 foreach($pattern in @('gh[pousr]_[A-Za-z0-9]{30,}','github_pat_[A-Za-z0-9_]{40,}','AKIA[0-9A-Z]{16}','-----BEGIN (RSA |EC |OPENSSH )?PRIVATE KEY-----','\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b','\b\d{3}\.\d{3}\.\d{3}-\d{2}\b','C:[\\/]Users[\\/]')){if([regex]::IsMatch($t,$pattern,[System.Text.RegularExpressions.RegexOptions]::IgnoreCase)){$issues.Add('Padrão sensível requer revisão, conteúdo omitido: '+$rel)}}
 if($modifiedAllowed -contains $rel){$prev=[regex]::Match($m,'(?m)^previous_revision: "([^"\r\n]+)"').Groups[1].Value;if(-not $prev.StartsWith($checkpoint+':'+$rel+'@')){$issues.Add('Referência de revisão anterior não atualizada: '+$rel)};$oldV=($prev -split '@')[-1];$parts=$oldV.Split('.');$expected=$parts[0]+'.'+([int]$parts[1]+1);$v=[regex]::Match($m,'(?m)^version: "([^"\r\n]+)"').Groups[1].Value;if($v -ne $expected){$issues.Add('Versão não incrementada: '+$rel)}}
}
$manifest=[System.IO.File]::ReadAllText((Join-Path $repoRoot 'governance/SOURCE-MANIFEST.md'))
foreach($n in 1..9){if(-not $manifest.Contains('SOURCE-'+$n.ToString('00'))){$issues.Add('Fonte ausente no manifesto: '+$n)}}
foreach($p in @('governance/sources/normative-integration-mandate-01.md','governance/sources/knowledge-foundation-mandate-01.md')){$actual=(Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $repoRoot $p)).Hash.ToLower();if(-not $manifest.Contains($actual)){$issues.Add('Hash de cópia canônica não corresponde ao manifesto: '+$p)}}
$niSource=[System.IO.File]::ReadAllText((Join-Path $repoRoot 'governance/sources/normative-integration-mandate-01.md'));$rawHash=[regex]::Match($niSource,'(?m)^source_sha256: "([^"\r\n]+)"').Groups[1].Value;if(-not $manifest.Contains($rawHash)){$issues.Add('Hash de recebimento NI ausente no manifesto')}
foreach($p in @('governance/mandates/m01-consolidated-mandate-1.0.md','governance/mandates/m01-consolidated-mandate-1.1.md','governance/sources/m01-mvp-original-mandate-01.md','governance/sources/m01-directory-construction-mandate-01.md','governance/sources/project-instructions-authoritative.md','governance/reviews/planner-m01-normative-review-01.md','governance/reviews/cto-m01-normative-review-02.md')){if(Test-Path -LiteralPath (Join-Path $repoRoot $p)){$issues.Add('Intake mudou ou fonte criada sem atualizar gate/evidência: '+$p)}}
$current=[System.IO.File]::ReadAllText((Join-Path $repoRoot 'status/CURRENT-STATUS.md'))
foreach($value in @('EXECUTED_WITH_SOURCE_TRANSFER_BLOCKER','NI-G01 BLOCKED','SOURCE_TRANSFER_PENDING','NORMATIVE_DIRECTION_APPROVED','PUBLICATION_ELIGIBLE','PUBLIC_EXPOSURE_ALLOWED','disputa admitida bloqueia','não suspende automaticamente','autoridade humana','retirada de consentimento','NOT_FROZEN','AC-KF-03-R1: BLOCKED','NOT_PREPARED','NOT_ESTABLISHED','CTO_NORMATIVE_BASELINE_INTEGRATION_REVIEW')){if(-not $current.Contains($value)){$issues.Add('Estado ou limite obrigatório ausente: '+$value)}}
foreach($p in @('README.md','AGENTS.md','governance/AUTHORITY-MODEL.md','governance/PROJECT-INSTRUCTIONS.md','governance/RAG-PROTOCOL.md','validation/KNOWLEDGE-READINESS.md')){if(-not ([System.IO.File]::ReadAllText((Join-Path $repoRoot $p))).Contains('CTO_NORMATIVE_BASELINE_INTEGRATION_REVIEW')){$issues.Add('Gate corrente ausente: '+$p)}}
$dec=[System.IO.File]::ReadAllText((Join-Path $repoRoot 'decisions/DECISION-REGISTER.md'));foreach($n in 1..16){if($dec -notmatch ('\| DEC-'+$n.ToString('00')+' \|')){$issues.Add('Decisão não preservada: '+$n)}};if(-not $dec.Contains('APPROVED_FRAMEWORK')){$issues.Add('Limite DEC-16 ausente')}
$val=[System.IO.File]::ReadAllText((Join-Path $repoRoot 'validation/VAL-NORMATIVE-INTEGRATION-01.md'))
$criteria=@([regex]::Matches($val,'(?m)^\| (AC-NI-\d{2}) \|[^\r\n]*? \| (PASS|FAIL|BLOCKED|NOT_EXECUTED) \|')|ForEach-Object {@{id=$_.Groups[1].Value;result=$_.Groups[2].Value}})
$counts=@{};foreach($state in @('PASS','FAIL','BLOCKED','NOT_EXECUTED')){$counts[$state]=@($criteria|Where-Object result -eq $state).Count}
if($criteria.Count -ne 16 -or $counts.PASS -ne 6 -or $counts.FAIL -ne 0 -or $counts.BLOCKED -ne 10 -or $counts.NOT_EXECUTED -ne 0){$issues.Add('Matriz AC-NI inconsistente com execução parcial')}
foreach($id in @('AC-NI-02','AC-NI-03','AC-NI-04','AC-NI-05','AC-NI-07','AC-NI-08','AC-NI-09','AC-NI-10','AC-NI-12','AC-NI-13')){if(@($criteria|Where-Object {$_.id -eq $id -and $_.result -eq 'BLOCKED'}).Count -ne 1){$issues.Add('Critério dependente de fonte indevidamente concluído: '+$id)}}
$trace=[System.IO.File]::ReadAllText((Join-Path $repoRoot 'validation/M01-NORMATIVE-TRACEABILITY.md'));if(-not $trace.Contains('Pares avaliados: 0') -or -not $trace.Contains('NOT_EVALUATED_SOURCE_TRANSFER_PENDING')){$issues.Add('Cobertura não avaliada deve ser explícita')}
$head=(& git -C $repoRoot rev-parse HEAD).Trim();if($head -ne $checkpoint){$issues.Add('HEAD foi alterado nesta intervenção')}
$changed=@(& git -C $repoRoot status --porcelain=v1 --untracked-files=all | ForEach-Object {$_.Substring(3).Replace('\','/')});foreach($p in $changed){if($modifiedAllowed -notcontains $p -and $newAllowed -notcontains $p){$issues.Add('Alteração fora do escopo declarado: '+$p)}}
$summary=[ordered]@{id='ANCESTRALIDADE-VAL-NORMATIVE-INTEGRATION-LOCAL-RESULT';date='2026-11-27';scope='NI05_PARTIAL_DOCUMENTARY_PREPARATION';checkpoint=$checkpoint;head=$head;markdown_files=$docs.Count;unique_ids=$ids.Count;metadata_checked=$metadata;relative_links_and_references_checked=$links;historical_files_preserved=$historical.Count;preservation=$historical;NI_G01='BLOCKED_SOURCE_TRANSFER_PENDING';essential_sources_received=0;essential_sources_required=7;revision_1_1='NOT_PREPARED';traceability=@{evaluated_pairs=0;coverage='NOT_EVALUATED_SOURCE_TRANSFER_PENDING';preserved=0;expanded=0;redistributed=0;superseded_by_decision=0;gaps=0;conflicts=0;unresolved=0;counts_mean='NO_PAIRS_CLASSIFIED_NOT_PROOF_OF_NO_GAPS_OR_CONFLICTS'};T01='NORMATIVE_DIRECTION_APPROVED';technical_contract='NOT_FROZEN';AC_KF_03_R1='BLOCKED';C10='OPEN_SOURCE_RECONCILIATION_PENDING';ac_ni=$criteria;counts=$counts;previous_validators_reexecuted=$false;cto_or_planner_tests_attributed_to_agent=$false;errors=@($issues);result=$(if($issues.Count -eq 0){'PASS'}else{'FAIL'});delivery='EXECUTED_WITH_SOURCE_TRANSFER_BLOCKER';limitations=@('Normative coverage and COR incorporation not validated because source-transfer gate is blocked','No independent remote retrieval of this uncommitted NI preparation','Byte hashes are working-tree session evidence and can vary with checkout line-ending normalization','Pattern checks are not exhaustive privacy/legal, YAML or rendering validation');next_gate='CTO_NORMATIVE_BASELINE_INTEGRATION_REVIEW'}
[System.IO.File]::WriteAllText($output,($summary|ConvertTo-Json -Depth 10),(New-Object System.Text.UTF8Encoding($false)))
if(-not (Test-Path -LiteralPath $output)){throw 'Evidência não gravada; referências à saída não satisfeitas'}
[pscustomobject]@{result=$summary.result;markdown_files=$docs.Count;unique_ids=$ids.Count;references_checked=$links;historical_files_preserved=$historical.Count;counts=$counts;errors=@($issues)}|ConvertTo-Json -Depth 6
if($issues.Count -gt 0){throw 'Validação NI falhou; consulte evidence/ni-validation.json'}
